 "Cohorte de enero": "January cohort",
 "<b style=\"font-size:25px;color:#7048e8\">La caída inicial</b><br><span style=\"font-size:20px;color:#241a45\">La mayoría se va en el primer día.</span>": "<b style=\"font-size:25px;color:#7048e8\">The initial drop</b><br><span style=\"font-size:20px;color:#241a45\">Most people leave on the first day.</span>",
 "<b style=\"font-size:25px;color:#b0752c\">Se aplana</b><br><span style=\"font-size:20px;color:#241a45\">Quien llega a la semana suele quedarse.</span>": "<b style=\"font-size:25px;color:#b0752c\">It flattens out</b><br><span style=\"font-size:20px;color:#241a45\">Those who make it to the first week usually stay.</span>",
